import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';

/**
 * One autogenerated sidebar, deliberately.
 *
 * A wiki that members edit should not need a config change to show a new
 * page. Order comes from `sidebar_position` in each file's frontmatter and
 * from the `_category_.json` in each folder — both live next to the content,
 * so adding a tool page is one file and no review of this file.
 */
const sidebars: SidebarsConfig = {
  wiki: [{ type: 'autogenerated', dirName: '.' }],
};

export default sidebars;
